from _lib import File
F=File('pre2020_honda250','o-h25','Honda CRF250R 2010-2019 by generation (2010-2013, 2014-2017, 2018-2021): what changed, dyno and weight, power character, tester settings, maps, known problems and fixes (knowledge push 2026-11)','Honda',['CRF250R','CRF250RX'],list(range(2010,2020)))
R=F.R; M='magazine'; C=['CRF250R']

# ---------------- 2010-2013 generation
s=F.src(M,"Motocross Action - 2010 Honda CRF250 race test","https://motocrossactionmag.com/real-tests-2010-mxa-race-test-of-the-honda-crf250","2009")
G=[2010,2011,2012,2013]
R('identity','2010 redesign',C,G,"The 2010 CRF250R was all new and the first fuel-injected one: a 50 mm throttle body with a 12-hole injector, a longer-stroke engine with 13.2:1 compression, 48 mm Showa fork (was 47 mm), a single muffler in place of the twin pipes, a 1.5 gal tank (was 1.9) and CRF450R-style geometry: 20 mm offset (was 22), 116 mm trail (was 125) and a 27.15 degree head angle (was 27.90). This platform ran 2010-2013.",{'offset_mm':20,'trail_mm':116,'head_angle_deg':27.15,'compression':'13.2:1','tank_gal':1.5,'fork':'Showa 48 mm coil spring'},'OEM',s)
R('power_feel','2010 dyno',C,[2010],"On a magazine dyno the 2010 CRF250R made 36.37 hp at 10,400 rpm and 19.18 lb-ft. It is a midrange engine: soft right off the bottom and flat near 11,000 rpm. The single muffler measured 96.5 dB.",{'peak_hp':36.37,'peak_rpm':10400,'peak_torque_lbft':19.18},'MEASURED',s,'high')
R('setups','2010-2011 tester settings',C,[2010,2011],"A magazine test crew's 2010-2011 CRF250R setup: fork 0.46 kg/mm springs (stock 0.45; stiffer still for riders over about 150-165 lb), 342 cc oil, compression 8 clicks out (stock 13), rebound 8 out, legs flush with the top clamp, steering damper 4 clicks out (stock 7). Shock 5.3 kg/mm spring, 105 mm sag (100 for heavier riders), high-speed compression 1-1/16 turns out (heavier riders 1/4 turn in), low-speed 7 clicks out, rebound 10 out (stock 11).",{'fork_spring':'0.46 kg/mm (stock 0.45)','fork':'342 cc, comp 8 out (stock 13), reb 8 out, flush','hpsd':'4 out (stock 7)','shock':'5.3 kg/mm, sag 105 mm, HSC 1-1/16 turns, LSC 7 out, reb 10 out'},'TUNER',s)
R('setups','2010-2013 gearing',C,G,"The 2010 CRF250R came geared 13/48 and Honda went to 13/49 for 2011. Testers were happy with 13/48 on the 2010 and several preferred to go back to it on the 2011 to make more use of the bottom end.",{'2010':'13/48','2011':'13/49'},'TUNER',s)
R('ecu_electronics','2010-2013 idle adjuster',C,G,"The fuel-injected 2010-2013 CRF250R needs no jetting. Idle is set on a click adjuster with about 90 clicks of range; the base setting is 60 clicks out and one click is about 100 rpm.",{'idle_base':'60 clicks out','per_click_rpm':100},'TUNER',s)
R('known_issues','2010-2013 weak points and fixes',C,G,"Repeated tester findings on the 2010-2013 CRF250R: headshake and oversteer from the steep geometry (stiffer fork springs, fork legs flush, 104-105 mm sag, a tighter steering stem nut, more steering damper, or a link about 2 mm longer, which drops the seat about 12 mm), a clutch that slips under hard use (one burned in six hours; stiffer springs), a front brake that fades with the plastic disc guard on (remove it), small footpegs that pack with mud on 2010-2011 bikes, a chain that wears the mud guard, and a frame cradle that will not sit level on an ordinary stand. A restrictive muffler holds the engine back; an aftermarket exhaust is the first power step.",{},'TUNER',s)
s=F.src(M,"Motocross Action - 2011 Honda CRF250 test","https://motocrossactionmag.com/2011-honda-crf250-motocross-test-honda-bets-the-bank-on-a-mini-version-of-the-crf450-warts-and-all","2010")
R('identity','2011 changes',C,[2011],"2011 CRF250R changes: a muffler 100 mm longer with a smaller outlet and a relocated bracket (2010 aftermarket exhausts do not fit), a steering damper piston enlarged from 20 to 24 mm, a revised EFI map (richer from 6,000-11,000 rpm, leaner above, more ignition advance), more compression damping at both ends and 13/49 gearing in place of 13/48.",{'gearing':'13/49'},'OEM',s)
R('power_feel','2011 dyno',C,[2011],"On a magazine dyno the 2011 CRF250R made 38.02 hp at 11,200 rpm and 20.04 lb-ft, the best peak in the 2011 250 class. Strong from 7,500 to 10,000 rpm, soft off idle. It measured 89.9 dB.",{'peak_hp':38.02,'peak_rpm':11200,'peak_torque_lbft':20.04},'MEASURED',s,'high')
s=F.src(M,"Motocross Action - 2012 Honda CRF250 test","https://motocrossactionmag.com/mxas-2012-honda-crf250-motocross-test-honda-tries-to-work-on-the-flaws","2011")
R('identity','2012 changes',C,[2012],"2012 CRF250R changes: throttle body reduced from 50 to 46 mm with a matching intake port and air boot, a link pull rod 4 mm longer with firmer initial shock valving, 30 cc more fork oil and stronger axle lugs, wider and longer footpegs, and Dunlop MX51 tyres front and rear.",{'throttle_body_mm':46,'pull_rod':'+4 mm'},'OEM',s)
R('power_feel','2012-2013 dyno and weight',C,[2012,2013],"On a magazine dyno the 2012 and 2013 CRF250R made 38.44 hp at 11,000 rpm and 20.0 lb-ft, holding over 38 hp from 10,300 to 11,300 rpm and 35.60 hp at 13,200 rpm. The 2012 weighed 222 lb, the lightest fuel-injected 250 four-stroke of its year. Midrange-led with a surge from 6,500 to 7,700 rpm.",{'peak_hp':38.44,'peak_rpm':11000,'peak_torque_lbft':20.0,'weight_lb_2012':222},'MEASURED',s,'high')
R('setups','2012 tester settings',C,[2012],"A magazine test crew's 2012 CRF250R setup: fork 0.46 kg/mm springs (stock 0.45), 357 cc oil (stock 372; come down in 5 cc steps), compression 8 clicks out (stock 6), rebound 11 out (stock 10), legs flush, steering damper 9 out (stock 11). Shock 5.3 kg/mm spring, 105 mm sag, high-speed compression 1-1/2 turns out (stock 1-5/8), low-speed 6 clicks out (stock 7), rebound 8 out (stock 9).",{'fork':'0.46 kg/mm, 357 cc, comp 8 out, reb 11 out, flush','hpsd':'9 out (stock 11)','shock':'sag 105 mm, HSC 1-1/2 turns, LSC 6 out, reb 8 out'},'TUNER',s)
s=F.src(M,"Motocross Action - 2013 Honda CRF250 test","https://motocrossactionmag.com/mxas-2013-honda-crf250-motocross-test-a-vastly-improved-bike-that-is-one-click-short-of-perfection","2012")
R('identity','2013 changes',C,[2013],"2013 CRF250R changes: stock fork springs up to 0.46 kg/mm, a larger fork sub-piston (37 mm, was 35), a larger high-speed adjuster seat in the shock, recalibrated fuel injection, a Dunlop MX51FA front tyre and a lighter CRF250-specific MX51 rear, and a front brake guard held by two bolts so it comes off easily.",{'fork_spring':'0.46 kg/mm'},'OEM',s)
R('setups','2013 tester settings',C,[2013],"A magazine test crew's 2013 CRF250R setup: fork stock 0.46 kg/mm springs, 363 cc oil, compression 6 clicks out (stock 7), rebound 9 out (stock 11), legs flush, steering damper 7 out (stock 9). Shock 5.3 kg/mm spring, 104 mm sag (100 for heavier riders), high-speed compression 1-3/4 turns out (stock 2), low-speed 8 clicks out, rebound 9 out (stock 11).",{'fork':'363 cc, comp 6 out, reb 9 out, flush','hpsd':'7 out (stock 9)','shock':'sag 104 mm, HSC 1-3/4 turns, LSC 8 out, reb 9 out'},'TUNER',s)

# ---------------- 2014-2017 generation
s=F.src(M,"Motocross Action - 2014 Honda CRF250 test","https://motocrossactionmag.com/mxas-2014-honda-crf250-motocross-test-honda-has-confused-us-with-a-bike-that-delivers-mixed-messages","2013")
G=[2014,2015,2016,2017]
R('identity','2014 redesign',C,G,"The 2014 CRF250R took the 2013 CRF450R's chassis layout: frame spars 37 mm lower, twin mufflers, a 1.66 gal tank, lower radiators, a new swingarm, linkage and shock. Engine changes: compression up from 13.2:1 to 13.5:1, a new piston, reshaped ports, dual-timing injection and a gearbox with wider gears rated 13% stronger. Steering geometry was carried over from the 2010-2013 bike. This platform ran 2014-2017. List price $7,599.",{'compression':'13.5:1','tank_gal':1.66,'msrp_usd':7599},'OEM',s)
R('power_feel','2014 dyno',C,[2014],"On a magazine dyno the 2014 CRF250R made 37.25 hp at 11,200 rpm and 19.72 lb-ft (2013 on the same dyno run: 37.19 hp at 10,700 rpm). It hits harder from 5,000 to 6,500 rpm than the old engine and is flat on top, which suits novices more than fast riders.",{'peak_hp':37.25,'peak_rpm':11200,'peak_torque_lbft':19.72},'MEASURED',s,'high')
R('setups','2014 tester settings',C,[2014],"A magazine test crew's 2014 CRF250R setup: fork stock 0.46 kg/mm springs, 367 cc oil (stock 357; heavier or faster riders add 6 cc a leg), compression 3 clicks out (stock 6), rebound 9 out (stock 11), legs flush, steering damper 7 out (stock 9). Shock 5.3 kg/mm spring, 104 mm sag (100 for heavier riders), high-speed compression 1 turn out (stock 1-1/4), low-speed 6 clicks out (stock 8), rebound 9 out (stock 11).",{'fork':'367 cc, comp 3 out (stock 6), reb 9 out, flush','hpsd':'7 out (stock 9)','shock':'sag 104 mm, HSC 1 turn, LSC 6 out, reb 9 out'},'TUNER',s)
R('known_issues','2014-2017 weak points and fixes',C,G,"Repeated tester findings on the 2014-2017 CRF250R: headshake and a wandering front at speed (tighten the steering stem nut until the play is gone, add steering damper, run the fork legs flush or lower), a soft clutch (stiffer springs or an aftermarket clutch), heavy twin mufflers of about 10 lb (a single-sided aftermarket system saves weight and, with a cam, was worth up to 4 hp in testing), the stock MX51FA front tyre knifing on 2014 bikes, two-piece side panels that are awkward for number backgrounds and a frame cradle that will not sit flat on a stand.",{'twin_muffler_weight_lb':10},'TUNER',s)
s=F.src(M,"Motocross Action - 2015 Honda CRF250 test","https://motocrossactionmag.com/2015-test-ride-honda-crf250","2014")
R('identity','2015 changes',C,[2015],"2015 CRF250R changes: Showa 49 mm SFF-Air TAC fork (three air chambers, 2-2.5 lb lighter) in place of coil springs, a three-map engine mode button, a larger-diameter exhaust with new mapping, firmer shock valving on the same 5.3 kg/mm spring, a 260 mm front disc, a softer throttle return spring and Dunlop MX52 tyres.",{'fork':'Showa SFF-Air TAC 49 mm','front_disc_mm':260,'maps':3},'OEM',s)
R('setups','2015 tester settings (air fork)',C,[2015],"A magazine test crew's 2015 CRF250R setup: fork inner chamber 180 psi (stock 174), balance chamber 170 psi (stock 163), compression 9 clicks out (stock 5), rebound 10 out (stock 12), legs flush, steering damper 7 out (stock 9). Shock 5.3 kg/mm spring, 104 mm sag (100 for heavier riders), high-speed compression 3-1/4 turns out (stock 3), low-speed 5 clicks out (stock 10), rebound 6 out (stock 8). The fork chambers affect one another, so change one at a time.",{'fork_psi':'inner 180 (stock 174), balance 170 (stock 163)','fork':'comp 9 out (stock 5), reb 10 out (stock 12), flush','shock':'sag 104 mm, HSC 3-1/4 turns, LSC 5 out, reb 6 out'},'TUNER',s)
R('ecu_electronics','2015-2017 map button',C,[2015,2016,2017],"The 2015-2017 CRF250R has three ignition maps on a throttle-side button (hold about a second per step): one flash stock, two mellow, three aggressive. Every magazine tester chose the aggressive map; it sharpens throttle response without adding peak power. There is no launch control. Honda's accessory tuning tool was about $620.",{'1_flash':'stock','2_flashes':'mellow','3_flashes':'aggressive (testers\' pick)'},'TUNER',s)
s=F.src(M,"Motocross Action - 2016 Honda CRF250 race test","https://motocrossactionmag.com/mxa-race-test-2016-honda-crf250","2015")
R('identity','2016 changes',C,[2016,2017],"2016 CRF250R changes: a lighter piston and rod, titanium exhaust valves, reshaped ports with more valve lift, compression up from 13.5:1 to 13.8:1, an exhaust resonator and larger muffler cores, fork legs 5 mm longer (slacker head angle, more trail), lower recommended fork pressures, adjusters with twice as many clicks per turn (so click counts are not comparable with 2015), a Schrader valve on the fork's outer chamber and a 34 mm chain roller (was 38).",{'compression':'13.8:1','fork_length':'+5 mm'},'OEM',s)
R('power_feel','2016 dyno and weight',C,[2016,2017],"On a magazine dyno the 2016 CRF250R made 38.89 hp at 11,700 rpm (2015: 37.30 at 11,000), with most of the gain up high: +2.70 hp at 12,000 rpm. It weighed 224 lb. Strong above 10,000 rpm and soft from low to mid; the Austrian 250s of that year peaked around 44 hp.",{'peak_hp':38.89,'peak_rpm':11700,'weight_lb':224},'MEASURED',s,'high')
R('setups','2016-2017 tester settings (air fork)',C,[2016,2017],"A magazine test crew's 2016 CRF250R setup: fork inner chamber 156 psi (stock 174), outer 8 psi (stock 12), balance 156 psi (stock 170), compression 6 clicks out, rebound 18 out (stock 24), legs flush with the top clamp (start 5 mm up and lower them for rough or fast tracks). Shock 5.3 kg/mm spring, 105 mm sag (100 for heavier riders), high-speed compression 2-3/4 turns out (stock 3), low-speed 10 clicks out, rebound 6 out (stock 8). Use the glyphs on the fork-cap sticker to be sure each pressure goes in the right valve.",{'fork_psi':'inner 156, outer 8, balance 156 (stock 174 / 12 / 170)','fork':'comp 6 out, reb 18 out (stock 24), flush','shock':'sag 105 mm, HSC 2-3/4 turns, LSC 10 out, reb 6 out'},'TUNER',s,'medium','Tested on the 2016; the 2017 CRF250R carried the same chassis and fork.')

# ---------------- 2018-2021 generation (DOHC, electric start)
s=F.src(M,"Motocross Action - 2018 Honda CRF250 race test","https://motocrossactionmag.com/mxa-race-test-2018-honda-crf250","2017")
G=[2018,2019]
R('identity','2018 redesign',C,G,"The 2018 CRF250R was all new: a DOHC engine in place of the Unicam, bore and stroke changed from 76.8 x 53.8 mm to 79 x 50.9 mm, 33 mm intake and 26 mm exhaust valves, twin exhaust ports, electric start, a single shared oil supply, Showa 49 mm coil-spring fork in place of the air fork, a titanium tank, the 2017 CRF450R frame layout with a swingarm 15 mm shorter and Dunlop MX3S tyres. Weight rose from 224 to 228 lb.",{'bore_stroke_mm':'79 x 50.9','valves_mm':'33 intake / 26 exhaust','fork':'Showa 49 mm coil spring','weight_lb':228},'OEM',s)
R('power_feel','2018 dyno',C,[2018],"On a magazine dyno the 2018 CRF250R peaked at 40.70 hp (1.81 more than the 2017) with 19.09 lb-ft, but it gave up 4.39 hp at 8,000 rpm to the old engine. It is a top-end engine that wants to be revved from 12,000 to 14,000 rpm, with little bottom or middle.",{'peak_hp':40.7,'peak_torque_lbft':19.09,'loss_at_8000_hp':4.39},'MEASURED',s,'high')
R('setups','2018-2019 tester settings',C,G,"A magazine test crew's 2018-2019 CRF250R setup: fork stock 4.6 N/mm springs, compression 7 clicks out (stock 9), rebound 13 out (stock 14), legs 3 mm up (stock 5). Shock stock 52 N/mm spring, 107 mm sag (stock recommendation 105), high-speed compression 3-1/4 turns out (stock 3-1/2), low-speed 9 clicks out (stock 11), rebound 7 out (stock 8). At 105 mm the bike oversteers on turn-in; 107 mm or more, or dropping the fork 2 mm, settles it and adds stability at speed.",{'fork':'4.6 N/mm, comp 7 out (stock 9), reb 13 out (stock 14), 3 mm up','shock':'52 N/mm, sag 107 mm, HSC 3-1/4 turns, LSC 9 out, reb 7 out'},'TUNER',s)
R('setups','2018-2019 gearing',C,G,"Stock gearing on the 2018-2019 CRF250R is 13/48. To cover the weak midrange testers ran a 49-tooth rear for fast riders and a 50 for vets and novices.",{'stock':'13/48','options':'13/49 fast riders, 13/50 vets and novices'},'TUNER',s)
R('ecu_electronics','2018-2019 maps',C,G,"The 2018-2019 CRF250R has three maps on the handlebar button: map 1 standard (the usual choice, mild engine braking), map 2 mellow, map 3 aggressive (more bottom and mid but more engine braking). Map 3 can be rewritten with Honda's tuning tool or an aftermarket Wi-Fi tuner. The 2019 added launch control with three settings.",{'map_1':'standard','map_2':'mellow','map_3':'aggressive, reprogrammable','launch_control':'2019 on, three modes'},'TUNER',s)
s=F.src(M,"Motocross Action - 2019 Honda CRF250 test","https://motocrossactionmag.com/2019-honda-crf250-the-real-test","2018")
R('identity','2019 changes',C,[2019],"2019 CRF250R changes: a new cam profile with valves closing 2 degrees earlier, revised ports, a right-side head pipe 50 mm shorter, a 44 mm throttle body (was 46), a five-hole piston oil jet, an updated clutch basket and judder spring, launch control, 1-1/8 in tapered bars in two clamp positions, a larger front caliper piston (30 mm) and black rims.",{'throttle_body_mm':44,'bars':'1-1/8 in tapered'},'OEM',s)
R('power_feel','2019 dyno and weight',C,[2019],"On a magazine dyno the 2019 CRF250R peaked at 42.40 hp (2018: 40.68), about 2 hp up from 8,000 to 10,000 rpm. It weighed 228 lb. Still linear and weak from low to mid; it pulls hardest from about 10,000 rpm up.",{'peak_hp':42.4,'weight_lb':228},'MEASURED',s,'high')
R('known_issues','2018-2019 weak points',C,G,"Known issues on the 2018-2019 CRF250R: 2018 clutch baskets failed and were covered by a recall (the 2019 has the updated basket and judder spring), the engine uses coolant when raced hard, the painted ignition and clutch covers scratch on the first ride, and the engine lacks bottom and midrange, which gearing only partly hides.",{},'TUNER',s)
R('chassis','2018-2019 handling',C,G,"The 2018-2019 CRF250R shares its frame layout with the 2017-on CRF450R. Against the 2015-2017 CRF250R the wheelbase is 3 mm shorter, the swingarm 15 mm shorter, the rake 0.1 degree slacker and the trail 2 mm less. Testers rated the handling intuitive and the coil fork the best part of the bike.",{},'TUNER',s)

if __name__=='__main__': F.write()
